CREATE OR REPLACE FUNCTION public.fn_ca_club_data_fact_put(p_club uuid, p_day date, p_kind text, p_game uuid, p_user uuid, p_fee numeric, p_buyins numeric, p_cashouts numeric, p_winnings numeric, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE captured boolean:=false; ok boolean:=true; d date; a timestamptz:=coalesce(p_at,now()); u uuid:=coalesce(p_user,'00000000-0000-0000-0000-000000000000');
BEGIN
 BEGIN
  PERFORM public.fn_ca_club_data_fact_put_pre_pacific(p_club,p_day,p_kind,p_game,p_user,p_fee,p_buyins,p_cashouts,p_winnings,p_at);
 EXCEPTION WHEN OTHERS THEN
  ok:=false;
  RAISE WARNING 'legacy Club Data projection: % %',SQLSTATE,SQLERRM;
 END;
 d:=public.fn_ca_club_data_pacific_day(a);
 BEGIN
 IF public.fn_ca_club_data_pacific_own('f:'||p_club||':'||p_day||':'||d||':'||p_game||':'||u||':'||ok) THEN
  INSERT INTO public.ca_club_data_pacific_fact AS f VALUES(p_club,p_day,d,p_kind,p_game,u,coalesce(p_fee,0),coalesce(p_buyins,0),coalesce(p_cashouts,0),coalesce(p_winnings,0),a,0,ok,CASE WHEN p_kind='CASH' AND p_fee>0 THEN 1 ELSE 0 END)
  ON CONFLICT(club_id,stat_date,game_id,user_id,utc_day,src,legacy_recorded) DO UPDATE SET
   fee=f.fee+EXCLUDED.fee,buyins=f.buyins+EXCLUDED.buyins,cashouts=f.cashouts+EXCLUDED.cashouts,winnings=f.winnings+EXCLUDED.winnings,last_at=greatest(f.last_at,EXCLUDED.last_at),hands=f.hands+EXCLUDED.hands;
 ELSE
  INSERT INTO public.ca_club_data_pacific_journal VALUES(p_club,p_day,d,p_kind,p_game,u,coalesce(p_fee,0),coalesce(p_buyins,0),coalesce(p_cashouts,0),coalesce(p_winnings,0),a,0,ok,CASE WHEN p_kind='CASH' AND p_fee>0 THEN 1 ELSE 0 END);
 END IF; captured:=true;
 EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,p_day,'live_fact',SQLSTATE||':'||SQLERRM);
  RAISE WARNING 'Pacific Club Data projection: % %',SQLSTATE,SQLERRM;
 END;
 BEGIN
 IF p_kind='CASH' AND p_fee>0 AND p_user IS NOT NULL AND nullif(current_setting('ca.pacific_rake_record',true),'') IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.ca_club_data_pacific_cash_records c WHERE c.rake_record_id=nullif(current_setting('ca.pacific_rake_record',true),'')::uuid
 AND c.game_id=p_game AND p_user=ANY(c.players) AND c.source_at=a) THEN
  INSERT INTO public.ca_club_data_pacific_cash_observations
  VALUES(nullif(current_setting('ca.pacific_rake_record',true),'')::uuid,p_user,p_day,d,p_game,a,0,CASE WHEN captured THEN p_club END,NULL,p_fee,ok,true);
 END IF;
 EXCEPTION WHEN OTHERS THEN INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,p_day,'live_cash_source',SQLSTATE||':'||SQLERRM); END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_club_data_hand_put(p_club uuid, p_table uuid, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE captured boolean:=false; d date:=public.fn_ca_club_data_pacific_day(p_at); u date:=(p_at AT TIME ZONE 'UTC')::date;
BEGIN
 BEGIN PERFORM public.fn_ca_club_data_hand_put_pre_pacific(p_club,p_table,p_at);
 EXCEPTION WHEN OTHERS THEN RAISE WARNING 'legacy hand projection: % %',SQLSTATE,SQLERRM; END;
 IF p_club IS NULL OR p_table IS NULL OR p_at IS NULL THEN RETURN; END IF;
 BEGIN
 IF public.fn_ca_club_data_pacific_own('h:'||p_club||':'||u||':'||d||':'||p_table) THEN
  INSERT INTO public.ca_club_data_pacific_hands AS h VALUES(p_club,u,d,p_table,1,0)
  ON CONFLICT(club_id,stat_date,table_id,utc_day,src) DO UPDATE SET hands=h.hands+1;
 ELSE INSERT INTO public.ca_club_data_pacific_hands_journal VALUES(p_club,u,d,p_table,1,0);
 END IF; captured:=true;
 EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,u,'live_hand',SQLSTATE||':'||SQLERRM);
  RAISE WARNING 'Pacific hand projection: % %',SQLSTATE,SQLERRM;
 END;
 BEGIN
 IF nullif(current_setting('ca.pacific_rake_record',true),'') IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.ca_club_data_pacific_cash_records c WHERE c.rake_record_id=nullif(current_setting('ca.pacific_rake_record',true),'')::uuid
 AND c.game_id=p_table AND c.source_at=p_at) THEN
  INSERT INTO public.ca_club_data_pacific_cash_observations
  VALUES(nullif(current_setting('ca.pacific_rake_record',true),'')::uuid,'00000000-0000-0000-0000-000000000000'::uuid,u,d,p_table,p_at,0,CASE WHEN captured THEN p_club END,NULL,0,true,true);
 END IF;
 EXCEPTION WHEN OTHERS THEN INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,u,'live_cash_source',SQLSTATE||':'||SQLERRM); END;
END $function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_data_fact_rake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$DECLARE old_context text:=current_setting('ca.pacific_rake_record',true); BEGIN BEGIN PERFORM public.fn_ca_club_data_pacific_cash_register(NEW.id); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Pacific cash registration failed: %',SQLERRM; END; PERFORM set_config('ca.pacific_rake_record',NEW.id::text,true); <<original_rake>> 
DECLARE
  v_day date; v_union uuid; v_table_club uuid; v_tourn uuid; v_found boolean;
  v_uid uuid; v_club uuid; v_n numeric; r record; v_any boolean := false;
  v_hand_clubs uuid[] := ARRAY[]::uuid[];
BEGIN
  IF NEW.created_at < public.fn_ca_club_data_fact_live_from() THEN EXIT original_rake; END IF;
  IF COALESCE(NEW.rake_amount, 0) = 0 THEN EXIT original_rake; END IF;
  v_day := (NEW.created_at AT TIME ZONE 'UTC')::date;

  IF NEW.tournament_id IS NULL AND NOT COALESCE(NEW.is_tournament, false) THEN
    -- A cash hand: each contributor's share, to the club their seat was bought in through.
    IF NEW.table_id IS NULL OR NEW.rake_amount <= 0 THEN EXIT original_rake; END IF;
    SELECT t.union_id, t.club_id, t.tournament_id, true
      INTO v_union, v_table_club, v_tourn, v_found
      FROM public.tables t WHERE t.id = NEW.table_id;
    IF v_found IS NOT TRUE OR v_tourn IS NOT NULL THEN EXIT original_rake; END IF;
    FOR r IN
      WITH e AS (
        SELECT x.key::uuid AS uid, (CASE WHEN x.value ~ '^[0-9]+(.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) AS contrib
          FROM jsonb_each_text(CASE WHEN jsonb_typeof(NEW.player_contributions) = 'object'
                                    THEN NEW.player_contributions ELSE '{}'::jsonb END) x
         WHERE x.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
           AND (CASE WHEN x.value ~ '^[0-9]+(.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) > 0
      ), s AS (SELECT e.uid, e.contrib, SUM(e.contrib) OVER () AS tot FROM e)
      SELECT COALESCE(public.fn_ca_cash_seat_club(NEW.table_id, s.uid),
                      public.fn_ca_cash_reporting_club(v_union, v_table_club, s.uid)) AS club_id,
             s.uid, NEW.rake_amount * s.contrib / s.tot AS fee
        FROM s ORDER BY 1, 2
    LOOP
      v_any := true;
      CONTINUE WHEN r.club_id IS NULL;
      CONTINUE WHEN public.fn_ca_launch_accounting_accepts(r.club_id, NEW.created_at) IS NOT TRUE;
      PERFORM public.fn_ca_club_data_fact_put(r.club_id, v_day, 'CASH', NEW.table_id, r.uid,
                                              r.fee, 0, 0, 0, NEW.created_at);
      IF NOT (r.club_id = ANY (v_hand_clubs)) THEN
        v_hand_clubs := v_hand_clubs || r.club_id;
        PERFORM public.fn_ca_club_data_hand_put(r.club_id, NEW.table_id, NEW.created_at);
      END IF;
    END LOOP;
    -- A raked hand that named nobody is the table's club's rake, whole.
    IF NOT v_any AND v_table_club IS NOT NULL
       AND public.fn_ca_launch_accounting_accepts(v_table_club, NEW.created_at) IS TRUE THEN
      PERFORM public.fn_ca_club_data_fact_put(v_table_club, v_day, 'CASH', NEW.table_id, NULL,
                                              NEW.rake_amount, 0, 0, 0, NEW.created_at);
      PERFORM public.fn_ca_club_data_hand_put(v_table_club, NEW.table_id, NEW.created_at);
    END IF;
    EXIT original_rake;
  END IF;

  -- A tournament fee: the named player's entry club, else split across the entries.
  IF NEW.tournament_id IS NULL THEN EXIT original_rake; END IF;
  SELECT tr.union_id, tr.club_id INTO v_union, v_table_club
    FROM public.tournaments tr WHERE tr.id = NEW.tournament_id;
  IF NEW.metadata ? 'user_id'
     AND (NEW.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    v_uid := (NEW.metadata->>'user_id')::uuid;
    SELECT tp.club_id INTO v_club FROM public.tournament_players tp
     WHERE tp.tournament_id = NEW.tournament_id AND tp.user_id = v_uid;
    v_club := COALESCE(v_club, public.fn_ca_cash_reporting_club(v_union, v_table_club, v_uid));
    IF v_club IS NOT NULL AND public.fn_ca_launch_accounting_accepts(v_club, NEW.created_at) IS TRUE THEN
      PERFORM public.fn_ca_club_data_fact_put(v_club, v_day, 'TOURNAMENT', NEW.tournament_id, v_uid,
                                              NEW.rake_amount, 0, 0, 0, NEW.created_at);
    END IF;
  ELSE
    SELECT count(*)::numeric INTO v_n FROM public.tournament_players tp
     WHERE tp.tournament_id = NEW.tournament_id;
    IF COALESCE(v_n, 0) = 0 THEN EXIT original_rake; END IF;
    FOR r IN
      SELECT COALESCE(tp.club_id, public.fn_ca_cash_reporting_club(v_union, v_table_club, tp.user_id)) AS club_id,
             tp.user_id
        FROM public.tournament_players tp
       WHERE tp.tournament_id = NEW.tournament_id
       ORDER BY 1, 2
    LOOP
      CONTINUE WHEN r.club_id IS NULL;
      CONTINUE WHEN public.fn_ca_launch_accounting_accepts(r.club_id, NEW.created_at) IS NOT TRUE;
      PERFORM public.fn_ca_club_data_fact_put(r.club_id, v_day, 'TOURNAMENT', NEW.tournament_id, r.user_id,
                                              NEW.rake_amount / v_n, 0, 0, 0, NEW.created_at);
    END LOOP;
  END IF;
  EXIT original_rake;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data fact (rake) failed for row %: %', NEW.id, SQLERRM;
  EXIT original_rake;
END;
 PERFORM set_config('ca.pacific_rake_record',coalesce(old_context,''),true); RETURN NULL; END;$function$

CREATE OR REPLACE FUNCTION public.fn_ca_bank_pending_cash_rake(p_hand_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  p public.cash_rake_pending%ROWTYPE;
  r record;
  v_union uuid;
  v_lock_timeout text := current_setting('lock_timeout');
  v_state text;
  v_msg text;
  v_epoch bigint;
  v_was_terminal boolean := false;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'cash_rake_bank_not_authorised' USING ERRCODE = '42501';
  END IF;
  -- Read BEFORE the attempt: an attempt under old code never carries a new epoch.
  v_epoch := smarter_private.money_law_epoch();

  BEGIN
    SELECT * INTO p FROM public.cash_rake_pending c
     WHERE c.hand_id = p_hand_id
       FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN
      -- Banked already, or another continuation holds it right now.
      RETURN jsonb_build_object('status', 'absent', 'hand_id', p_hand_id);
    END IF;

    /* A DETERMINISTIC REFUSAL STANDS UNTIL THE LAW CHANGES (20261118192000).
       Answer it without running it again. */
    IF p.terminal_epoch IS NOT NULL AND p.terminal_epoch >= v_epoch THEN
      RETURN jsonb_build_object('status', 'terminal', 'hand_id', p_hand_id,
                                'error', p.last_error, 'terminal_at', p.terminal_at);
    END IF;
    v_was_terminal := p.terminal_epoch IS NOT NULL;

    /* NEVER WAIT FOR THE SHARED WALLET ROW. The union this rake is routed to
       is the game's stamp, read as atomic_distribute_rake reads it. A wallet
       someone holds leaves the obligation exactly where it is; whoever holds
       it is not this hand's problem and this hand is not theirs. */
    SELECT CASE WHEN COALESCE(t.is_private, false) THEN NULL ELSE t.union_id END
      INTO v_union
      FROM public.tables t WHERE t.id = p.table_id;
    IF v_union IS NOT NULL THEN
      PERFORM 1 FROM public.union_wallets w
        WHERE w.union_id = v_union
          FOR NO KEY UPDATE NOWAIT;
    END IF;
    PERFORM set_config('lock_timeout', '250ms', true);

    -- The call the envelope made, argument for argument.
    SELECT * INTO r
      FROM public.atomic_distribute_rake(
        p.table_id,
        (p.rake->>'club_id')::uuid,
        p.hand_id,
        p.hand_number::integer,
        (p.rake->>'amount')::numeric,
        COALESCE((p.rake->>'bbj')::numeric, 0),
        NULLIF(p.rake->>'pot', '')::numeric,
        NULLIF(p.rake->>'num_players', '')::integer,
        COALESCE(p.rake->'contributions', '{}'::jsonb),
        NULLIF(p.rake->>'tournament_id', '')::uuid,
        COALESCE(p.rake->'returned_uncalled', '{}'::jsonb),
        COALESCE(NULLIF(p.rake->>'method', ''), 'WEIGHTED_CONTRIBUTED')
      );
    IF NOT FOUND OR NOT (
      COALESCE(r.applied, false)
      OR COALESCE(r.already_processed, false)
      OR r.rake_record_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'rake obligation did not produce a receipt for hand %', p_hand_id;
    END IF;

    DELETE FROM public.cash_rake_pending c WHERE c.hand_id = p_hand_id;
    IF v_was_terminal THEN
      UPDATE public.financial_alerts a
         SET resolved = true, resolved_at = now(),
             resolution = 'banked after the money law that refused it changed'
       WHERE a.source = 'bank_obligation_terminal_refusal' AND NOT a.resolved
         AND a.context->>'hand_id' = p_hand_id::text AND a.context->>'obligation' = 'rake';
    END IF;
    PERFORM set_config('lock_timeout', v_lock_timeout, true);
    RETURN jsonb_build_object(
      'status', 'banked', 'hand_id', p_hand_id, 'amount', p.amount,
      'applied', r.applied, 'already_processed', r.already_processed,
      'recovered', r.recovered, 'rake_record_id', r.rake_record_id,
      'route', r.spendable_route, 'union_id', r.union_id_out);
  EXCEPTION
    WHEN lock_not_available THEN
      PERFORM set_config('lock_timeout', v_lock_timeout, true);
      RETURN jsonb_build_object('status', 'busy', 'hand_id', p_hand_id);
    WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
  END;
  PERFORM set_config('lock_timeout', v_lock_timeout, true);

  -- Refused: nothing above was kept. The obligation stays, and says why.
  IF smarter_private.bank_refusal_is_transient(v_state) THEN
    UPDATE public.cash_rake_pending c
       SET attempts = c.attempts + 1,
           last_attempt_at = clock_timestamp(),
           last_error = left(v_state || ': ' || v_msg, 500)
     WHERE c.hand_id = p_hand_id;
    RETURN jsonb_build_object('status', 'refused', 'hand_id', p_hand_id,
                              'sqlstate', v_state, 'error', v_msg);
  END IF;

  /* A REFUSAL NO RETRY CAN CHANGE (20261118192000): held under this law,
     named once at its source, and no longer holding its hand or table. */
  UPDATE public.cash_rake_pending c
     SET attempts = c.attempts + 1,
         last_attempt_at = clock_timestamp(),
         last_error = left(v_state || ': ' || v_msg, 500),
         terminal_epoch = v_epoch,
         terminal_at = clock_timestamp()
   WHERE c.hand_id = p_hand_id;
  IF FOUND AND NOT EXISTS (
    SELECT 1 FROM public.financial_alerts a
     WHERE a.source = 'bank_obligation_terminal_refusal'
       AND NOT a.resolved
       AND a.context->>'hand_id' = p_hand_id::text
       AND a.context->>'obligation' = 'rake'
  ) THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('critical', 'bank_obligation_terminal_refusal',
      'A stored hand rake was refused by a rule no retry can change: ' || left(v_msg, 200)
        || '. It is held on its own row, not lost, and is asked again when the money law next changes.',
      jsonb_build_object('obligation', 'rake', 'hand_id', p_hand_id, 'table_id', p.table_id,
                         'hand_number', p.hand_number, 'amount', p.amount, 'sqlstate', v_state,
                         'error', left(v_msg, 500), 'law_epoch', v_epoch));
  END IF;
  RETURN jsonb_build_object('status', 'terminal', 'hand_id', p_hand_id,
                            'sqlstate', v_state, 'error', v_msg);
END $function$

CREATE OR REPLACE FUNCTION public.fn_lightning_owed_leave_returns_to_pool(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_seat    record;
  v_cluster uuid;
  v_mode    text;
  v_owed    integer;
BEGIN
  IF NOT coalesce(public.fn_caller_is_engine(), false) THEN
    RAISE EXCEPTION 'fn_lightning_owed_leave_returns_to_pool is engine-only' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR p_table_id IS NULL OR p_seat_number IS NULL OR p_occupancy_id IS NULL THEN
    RAISE EXCEPTION 'DEPARTURE_IDENTITY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'platform_frozen');
  END IF;

  SELECT ts.id, ts.leave_pending, tb.cluster_id
    INTO v_seat
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE ts.occupancy_id = p_occupancy_id AND ts.user_id = p_user_id
     AND ts.table_id = p_table_id AND ts.seat_number = p_seat_number
     AND ts.left_at IS NULL
   FOR UPDATE OF ts;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'stale_occupancy');
  END IF;
  IF NOT coalesce(v_seat.leave_pending, false) THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'not_pending');
  END IF;

  SELECT g.id INTO v_cluster
    FROM public.cash_games g
   WHERE g.id = v_seat.cluster_id AND g.cluster_mode = 'lightning';
  IF v_cluster IS NULL THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'not_lightning');
  END IF;

  SELECT d.leave_mode INTO v_mode
    FROM public.seat_departure_requests d
   WHERE d.occupancy_id = p_occupancy_id AND d.user_id = p_user_id
     AND d.table_id = p_table_id AND d.seat_number = p_seat_number
   FOR UPDATE;
  IF v_mode IS DISTINCT FROM 'voluntary' THEN
    RETURN jsonb_build_object('returned', false,
      'reason', CASE WHEN v_mode IS NULL THEN 'no_request' ELSE 'forced' END);
  END IF;

  IF public.fn_lightning_player_live_hand(p_user_id, v_cluster) IS NOT NULL THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'in_hand');
  END IF;

  -- The leave door itself decides what is owed, exactly as it refuses the
  -- cash-out (and fn_lightning_hands_owed asks the same question).
  v_owed := coalesce((public.fn_cash_leave_check(p_user_id, p_table_id) ->> 'hands_remaining')::integer, 0);
  IF v_owed <= 0 THEN
    RETURN jsonb_build_object('returned', false, 'reason', 'not_owed');
  END IF;

  DELETE FROM public.seat_departure_requests d
   WHERE d.occupancy_id = p_occupancy_id AND d.user_id = p_user_id
     AND d.table_id = p_table_id AND d.seat_number = p_seat_number
     AND d.leave_mode = 'voluntary';

  UPDATE public.table_seats
     SET leave_pending = false,
         is_sitting_out = false,
         status = 'active'
   WHERE id = v_seat.id;

  UPDATE public.cash_player_session
     SET hr_blind_off = true
   WHERE player_id = p_user_id AND scope_type = 'table' AND scope_id = p_table_id
     AND closed_at IS NULL;

  RETURN jsonb_build_object('returned', true, 'hands_remaining', v_owed,
    'cluster_id', v_cluster, 'occupancy_id', p_occupancy_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cash_cluster_commit_must_move(p_game_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  g            record;
  v_conv       record;
  v_state      jsonb;
  v_live       integer;
  v_off        integer;
  v_inflight   integer;
  v_before     text;
  v_after      text;
  v_chips      numeric;
  v_epoch      integer;
  v_sessions   integer := 0;
  v_players    jsonb := '[]'::jsonb;
  v_slots      integer := 0;
  v_expired    integer := 0;
  v_released   integer := 0;
  v_tables     integer := 0;
  v_halted     integer := 0;
  v_stranded   integer := 0;
  v_open       integer := 0;
  v_locked_seats    uuid[];
  v_locked_sessions uuid[];
  v_drained         boolean := false;
BEGIN
  -- GATED, because this is the step that lets the physical tables deal again.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false, 'reason', 'platform_frozen');
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): THE DRAIN IS POLLED
  -- BEFORE THE LOCK. The tick asks this every pass while the drain empties,
  -- and the cheap not-ready answer does not need, and no longer takes, the
  -- Cluster row every formation, tick and conversion serialises on. The
  -- authoritative count below still runs under the lock.
  SELECT count(*)::integer INTO v_inflight
    FROM public.lightning_instance li
   WHERE li.cluster_id = p_game_id AND li.state IN ('forming', 'reserved', 'dealing', 'settling');
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false,
      'reason', 'instances_in_flight', 'instances_in_flight', v_inflight,
      'cluster_mode', (SELECT cluster_mode FROM public.cash_games WHERE id = p_game_id));
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND conversion_request_id = p_request_id;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
                WHERE conversion_request_id = p_request_id) THEN
      RETURN jsonb_build_object('ok', false, 'reverted', false,
        'reason', 'request_id_belongs_to_another_cluster');
    END IF;
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'no_such_conversion');
  END IF;
  IF v_conv.to_mode IS DISTINCT FROM 'must_move' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false,
      'reason', 'not_a_pending_off_conversion', 'to_mode', v_conv.to_mode);
  END IF;
  -- A RETRY OF A COMMITTED REVERSION is told what happened. reverted is read
  -- off the Cluster, as commit_lightning's converted is: the record says what
  -- this conversion did, the mode says what the Cluster is now.
  IF v_conv.status = 'committed' THEN
    RETURN jsonb_build_object('ok', true, 'reverted', g.cluster_mode = 'must_move',
      'reason', 'already_committed', 'conversion_id', v_conv.id,
      'epoch_after', v_conv.epoch_after, 'cluster_mode', g.cluster_mode);
  END IF;
  IF v_conv.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false,
      'reason', 'conversion_already_closed', 'status', v_conv.status,
      'abort_reason', v_conv.abort_reason, 'cluster_mode', g.cluster_mode);
  END IF;
  IF g.cluster_mode IS DISTINCT FROM 'pending_off' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'wrong_state',
      'cluster_mode', g.cluster_mode);
  END IF;

  -- SPECIFICATION STEP 10. A population that rose back above OFF before the
  -- drain point cancels the reversion, while Lightning is still enabled.
  v_state := public.fn_cash_cluster_lightning_state(g.id);
  v_live  := coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0);
  v_off   := coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0);
  IF coalesce(g.lightning_enabled, false) AND g.enabled IS NOT DISTINCT FROM true AND v_live > v_off THEN
    RETURN public.fn_cash_cluster_abort_pending_off(
      g.id, p_request_id, 'population_rose_above_off_threshold_before_the_drain_point')
      || jsonb_build_object('ok', false, 'reverted', false);
  END IF;

  -- THE DRAIN POINT. Not a raise: a structured not-ready answer the caller
  -- polls, exactly as commit_lightning answers hands_in_flight.
  SELECT count(*)::integer INTO v_inflight
    FROM public.lightning_instance li
   WHERE li.cluster_id = g.id AND li.state IN ('forming', 'reserved', 'dealing', 'settling');
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false,
      'reason', 'instances_in_flight', 'instances_in_flight', v_inflight,
      'cluster_mode', g.cluster_mode);
  END IF;

  -- THE MONEY, AS EVERY COLUMN OF EVERY ROW. A sum is satisfied by two stacks
  -- that swapped; this is not. Seats of every member table, the Cluster's
  -- cash sessions (baseline, stay clock, rejoin window, join time), and its
  -- blind ledger (what is owed). This transition writes none of them.
  -- THE MONEY, AS EVERY COLUMN OF EVERY LIVE ROW, UNDER ROW LOCKS
  -- (20261007222717). The two digests used to run unlocked at READ COMMITTED
  -- over every historical row, so ordinary concurrent seat or session traffic
  -- committing between them - an engine is_sitting_out update, a departure
  -- request, a session evaluation - could trip the assertion as a false
  -- alarm, and its cost grew with the Cluster's whole history. The live rows
  -- are taken FOR SHARE first, in the estate's order: the Cluster row is
  -- already held FOR UPDATE, then the seats in seat-id order (as formation
  -- takes its anchors), then the open cash sessions, then the blind ledger.
  -- Both digests cover exactly those live rows; a row already dead cannot
  -- change under this transaction's locks and proves nothing about what this
  -- transition wrote.
  -- THE REVERSION COMPARES THE ROWS IT LOCKED (2026-10-09, Phase 12 load
  -- and chaos): the same locks in the same order, and the ids they took are
  -- kept, so both digests below cover exactly those rows (and any row this
  -- transaction wrote). A row lock cannot stop an INSERT: a player arriving
  -- during the drain whose seat and cash session committed between the two
  -- digests tripped LIGHTNING_REVERSION_MOVED_MONEY although nothing here
  -- moved (measured in the conversion storm, a false financial alarm).
  SELECT coalesce(array_agg(x.id ORDER BY x.id), ARRAY[]::uuid[]) INTO v_locked_seats FROM (
    SELECT ts.id FROM public.table_seats ts
     WHERE ts.left_at IS NULL
       AND ts.table_id IN (SELECT tb.id FROM public.tables tb WHERE tb.cluster_id = g.id)
     ORDER BY ts.id
       FOR SHARE) x;
  SELECT coalesce(array_agg(x.id ORDER BY x.id), ARRAY[]::uuid[]) INTO v_locked_sessions FROM (
    SELECT s.id FROM public.cash_player_session s
     WHERE s.cluster_id = g.id AND s.closed_at IS NULL
     ORDER BY s.id
       FOR SHARE) x;
  PERFORM 1 FROM public.lightning_blind_ledger bl
   WHERE bl.cluster_id = g.id
   ORDER BY bl.player_id
   FOR SHARE;
  -- THE MODE CHANGES UNDER THE CLUSTER'S MODE LOCK (2026-10-15, Lightning
  -- Phase 12 load and chaos): EXCLUSIVE, after the row locks above and
  -- before the pool is closed. An arrival whose seat trigger read
  -- 'lightning' first (the drain opens PENDING_OFF and reverts in one
  -- transaction) has committed its pool session when this returns, and the
  -- close below sees it; one after waits for this commit and reads
  -- 'must_move'. No pool session at the old epoch outlives the reversion.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended('lightning_cluster_mode:' || g.id::text, 0));

  SELECT md5(coalesce(string_agg(x.r, '|' ORDER BY x.r), '')) INTO v_before FROM (
      SELECT 'ts:' || to_jsonb(ts)::text AS r
        FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
       WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
         AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'cps:' || to_jsonb(s)::text FROM public.cash_player_session s
       WHERE s.cluster_id = g.id AND s.closed_at IS NULL
         AND (s.id = ANY (v_locked_sessions) OR s.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'bl:' || to_jsonb(bl)::text FROM public.lightning_blind_ledger bl WHERE bl.cluster_id = g.id
    ) x;
  SELECT coalesce(sum(ts.stack), 0) INTO v_chips
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL;

  -- EVERY OPEN POOL SESSION EXITS, ONE pool_player_left EACH. The cash
  -- session it is subordinate to stays open: leaving Lightning does not end
  -- the player's cash session, and the anchor seat they never left is where
  -- they now play.
  -- LIGHTNING PHASE 13 (20261009235505): AN EMERGENCY DRAIN SAYS SO. The
  -- sessions a drain releases exit 'lightning_drained', the ones a falling
  -- population releases 'lightning_off'; the transition is the same.
  v_drained := EXISTS (SELECT 1 FROM public.lightning_cluster_drain d
                        WHERE d.cluster_id = g.id AND d.completed_at IS NULL);
  WITH exited AS (
    UPDATE public.lightning_pool_session ps
       SET exited_at = GREATEST(clock_timestamp(), ps.entered_at),
           exit_reason = CASE WHEN v_drained THEN 'lightning_drained' ELSE 'lightning_off' END,
           state = 'closed',
           ending_stack = public.fn_lightning_pool_stack(ps.id),
           updated_at = clock_timestamp()
     WHERE ps.cluster_id = g.id AND ps.exited_at IS NULL
    RETURNING ps.id, ps.cluster_epoch, ps.player_id, ps.anchor_seat_id, ps.ending_stack, ps.exited_at
  ), logged AS (
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload, cluster_epoch, request_id)
    SELECT g.id, ts.table_id, 'pool_player_left', jsonb_build_object(
             'cluster_id', g.id, 'cluster_epoch', e.cluster_epoch, 'player_id', e.player_id,
             'pool_session_id', e.id, 'anchor_seat_id', e.anchor_seat_id, 'reason', CASE WHEN v_drained THEN 'lightning_drained' ELSE 'lightning_off' END,
             'ending_stack', e.ending_stack, 'seat_table_id', ts.table_id, 'seat_number', ts.seat_number,
             'conversion_id', v_conv.id, 'at', e.exited_at),
           e.cluster_epoch, p_request_id
      FROM exited e LEFT JOIN public.table_seats ts ON ts.id = e.anchor_seat_id
    RETURNING 1
  )
  SELECT (SELECT count(*)::integer FROM exited),
         (SELECT coalesce(jsonb_agg(e.player_id ORDER BY e.player_id), '[]'::jsonb) FROM exited e),
         (SELECT count(*)::integer FROM exited e
           WHERE NOT EXISTS (SELECT 1 FROM public.table_seats ts
                              WHERE ts.id = e.anchor_seat_id AND ts.left_at IS NULL
                                AND ts.user_id = e.player_id)),
         (SELECT count(*)::integer FROM logged)
    INTO v_sessions, v_players, v_stranded, v_open;
  IF v_open IS DISTINCT FROM v_sessions THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_LOST_AN_EVENT: cluster % exited % pool session(s) and logged % pool_player_left',
      g.id, v_sessions, v_open USING ERRCODE = 'check_violation';
  END IF;
  -- A PLAYER THE POOL LETS GO HAS A SEAT TO PLAY AT. The seat trigger exits a
  -- session the moment its anchor is left, so this cannot fire as written; it
  -- is here so that it fires the day something breaks that.
  IF v_stranded > 0 THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_STRANDED_A_PLAYER: cluster % released % pool player(s) whose anchor seat is not theirs and live',
      g.id, v_stranded USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.lightning_pool_slot sl
     SET closed_at = GREATEST(clock_timestamp(), sl.opened_at), close_reason = 'lightning_off',
         updated_at = clock_timestamp()
   WHERE sl.cluster_id = g.id AND sl.closed_at IS NULL;
  GET DIAGNOSTICS v_slots = ROW_COUNT;

  -- Only Lightning-specific transient state is wiped. A pending reservation
  -- cannot outlive its instance in practice; one that did is expired, not
  -- deleted, so the row still says what happened to it.
  UPDATE public.lightning_reservation r
     SET state = 'expired', resolved_at = clock_timestamp(), reason = coalesce(r.reason, 'lightning_off')
   WHERE r.cluster_id = g.id AND r.state = 'pending';
  GET DIAGNOSTICS v_expired = ROW_COUNT;
  UPDATE public.lightning_reservation r
     SET state = 'released', resolved_at = clock_timestamp(), reason = coalesce(r.reason, 'lightning_off')
   WHERE r.cluster_id = g.id AND r.state = 'committed';
  GET DIAGNOSTICS v_released = ROW_COUNT;

  -- THE NEXT EPOCH, IN must_move. ca.epoch_reason is what the epoch writer
  -- records as started_by.
  PERFORM set_config('ca.epoch_reason', 'lightning_off', true);
  PERFORM set_config('ca.request_id', p_request_id::text, true);
  v_epoch := g.cluster_epoch + 1;
  UPDATE public.cash_games
     SET cluster_mode = 'must_move', cluster_epoch = v_epoch, updated_at = now()
   WHERE id = g.id;

  -- THE TABLES DEAL AGAIN. Only a halt Lightning placed is lifted; a halt
  -- somebody else put on a member table is theirs to lift. The engine polls
  -- the halt between hands, so this is what restarts the physical game.
  -- The engine's acknowledgement of that halt goes with it, so the next
  -- PENDING_ON waits for a fresh observation of its own halt.
  IF g.enabled IS NOT DISTINCT FROM true THEN
    UPDATE public.tables tb
       SET dealing_halted_at = NULL, dealing_halted_reason = NULL, dealing_halt_observed_at = NULL
     WHERE tb.cluster_id = g.id AND tb.dealing_halted_reason IN ('lightning', 'lightning_pending_on');
    GET DIAGNOSTICS v_tables = ROW_COUNT;
  ELSE
    -- 20261007222717: THE GAME ITSELF IS DISABLED. A reversion is a seating
    -- transition, not a licence to deal: the member tables stay halted for
    -- the game-close path that owns a disabled game, and the result and the
    -- event both say so (halts_kept_game_disabled).
    v_tables := 0;
  END IF;
  SELECT count(*)::integer INTO v_halted
    FROM public.tables tb
   WHERE tb.cluster_id = g.id AND tb.dealing_halted_at IS NOT NULL
     AND coalesce(tb.is_deleted, false) = false AND coalesce(tb.lifecycle, '') <> 'closed';

  SELECT md5(coalesce(string_agg(x.r, '|' ORDER BY x.r), '')) INTO v_after FROM (
      SELECT 'ts:' || to_jsonb(ts)::text AS r
        FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
       WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
         AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'cps:' || to_jsonb(s)::text FROM public.cash_player_session s
       WHERE s.cluster_id = g.id AND s.closed_at IS NULL
         AND (s.id = ANY (v_locked_sessions) OR s.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'bl:' || to_jsonb(bl)::text FROM public.lightning_blind_ledger bl WHERE bl.cluster_id = g.id
    ) x;
  IF v_after IS DISTINCT FROM v_before THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_MOVED_MONEY: cluster % seats, cash sessions or blind ledger changed across the reversion (% -> %), and a mode change is a seating transition, not an economic transaction',
      g.id, v_before, v_after USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*)::integer INTO v_open
    FROM public.lightning_pool_session ps WHERE ps.cluster_id = g.id AND ps.exited_at IS NULL;
  IF v_open > 0 THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_LEFT_A_POOL_SESSION_OPEN: cluster % still has % open pool session(s) in must_move',
      g.id, v_open USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.cash_cluster_conversion
     SET status = 'committed', epoch_after = v_epoch, closed_at = clock_timestamp(),
         chips_at_commit = v_chips
   WHERE id = v_conv.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, request_id)
  VALUES (g.id, 'lightning_off', jsonb_build_object(
    'conversion_id', v_conv.id, 'conversion_request_id', p_request_id,
    'from_mode', 'lightning', 'to_mode', 'must_move',
    'trigger_population', v_conv.trigger_population, 'population_at_commit', v_live,
    'on_threshold', v_conv.on_threshold, 'off_threshold', v_conv.off_threshold,
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions_exited', v_sessions, 'players', v_players, 'slots_closed', v_slots,
    'reservations_expired', v_expired, 'reservations_released', v_released,
    'tables_released', v_tables, 'tables_still_halted', v_halted,
    'halts_kept_game_disabled', g.enabled IS DISTINCT FROM true,
    'chip_total', v_chips, 'money_md5', v_before, 'drained', v_drained), p_request_id);

  RETURN jsonb_build_object('ok', true, 'reverted', true, 'ready', true, 'reason', 'must_move',
    'conversion_id', v_conv.id, 'cluster_mode', 'must_move',
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions_exited', v_sessions, 'slots_closed', v_slots,
    'reservations_expired', v_expired, 'reservations_released', v_released,
    'tables_released', v_tables, 'tables_still_halted', v_halted,
    'halts_kept_game_disabled', g.enabled IS DISTINCT FROM true,
    'chip_total', v_chips, 'population_at_commit', v_live, 'drained', v_drained);
END;
$function$
